CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.user_roles(user_id,role) VALUES ('4dac9829-8023-4d97-b195-c0ad4143effd','admin');
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'); $$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin() TO anon,authenticated,service_role;
DO $$ DECLARE p record; BEGIN FOR p IN SELECT * FROM pg_policies WHERE schemaname='public' AND tablename IN ('faculties','books','students','library_visits') AND policyname LIKE '%staff%' LOOP
IF p.cmd='INSERT' THEN EXECUTE format('ALTER POLICY %I ON public.%I WITH CHECK (public.is_admin())',p.policyname,p.tablename);
ELSIF p.cmd IN ('UPDATE','ALL') THEN EXECUTE format('ALTER POLICY %I ON public.%I USING (public.is_admin()) WITH CHECK (public.is_admin())',p.policyname,p.tablename);
ELSE EXECUTE format('ALTER POLICY %I ON public.%I USING (public.is_admin())',p.policyname,p.tablename); END IF;
END LOOP; END $$;
ALTER POLICY faculties_public_read ON public.faculties TO anon,authenticated;
ALTER POLICY books_public_read ON public.books TO anon,authenticated;
ALTER POLICY visits_public_insert ON public.library_visits TO anon,authenticated WITH CHECK (student_id ~ '^[0-9]{4,20}$' AND char_length(btrim(student_name)) BETWEEN 3 AND 120 AND book_id IS NOT NULL AND book_name_manual IS NULL AND EXISTS(SELECT 1 FROM public.faculties f WHERE f.id=faculty_id AND f.is_active));
CREATE TABLE public.visitor_visits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL CHECK(char_length(btrim(full_name)) BETWEEN 3 AND 120), specialty text NOT NULL CHECK(char_length(btrim(specialty)) BETWEEN 2 AND 160), visit_date date NOT NULL DEFAULT (now() AT TIME ZONE 'Africa/Cairo')::date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.visitor_visits TO anon,authenticated;
GRANT SELECT,UPDATE,DELETE ON public.visitor_visits TO authenticated;
GRANT ALL ON public.visitor_visits TO service_role;
ALTER TABLE public.visitor_visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY visitor_submit ON public.visitor_visits FOR INSERT TO anon,authenticated WITH CHECK (visit_date=(now() AT TIME ZONE 'Africa/Cairo')::date);
CREATE POLICY visitor_admin_read ON public.visitor_visits FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY visitor_admin_update ON public.visitor_visits FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY visitor_admin_delete ON public.visitor_visits FOR DELETE TO authenticated USING(public.is_admin());
CREATE TRIGGER visitor_updated_at BEFORE UPDATE ON public.visitor_visits FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX visitor_visits_date_idx ON public.visitor_visits(visit_date);
